// Strongroom operator kit — procedural, low-poly attachments per operator.
//
// ES module; depends only on `three`, ./palette.js and ./body-metrics.js (the
// latter generated by tools/build.mjs from the shipped GLBs). Everything is
// authored in the body's BIND space (model units, feet at y = 0, facing +Z,
// character's left = +X, T-pose) and skinned rigidly (weight 1.0) to one bone
// per part, so it merges into the body's SkinnedMesh geometry: 0 extra draw
// calls, same palette material, same skeleton.
//
//   import { buildKit, mergeKitIntoBody, operatorMaterial } from './attachments.js';
//   const kit = buildKit('cinder', { body: 'ct', lod: 0, skeleton: mesh.skeleton });
//   mesh.geometry = mergeKitIntoBody(mesh.geometry, kit.geometry);
//   mesh.material = operatorMaterial({ side: 'attack', tint: 'enemy' });
//
// Budgets (DESIGN.md §9.2): <= 600 tris per operator at LOD0. LOD1 kits drop
// small details and widen the team-tinted regions for 30 m readability.
// Original designs only — generic modern tactical gear, no gore, no IP.

import * as THREE from 'three';
import { slotUV, SLOTS, paletteRGBA, emissiveMaskRGBA, PALETTE_SIZE, TINTS, TEAM_EMISSIVE_INTENSITY } from './palette.js';
import { BODY_METRICS } from './body-metrics.js';

export * from './palette.js';
export { BODY_METRICS };

/** The shared 43-joint rig (identical in soldier_ct / soldier_t), glTF names. */
export const JOINTS = Object.freeze(['Root', 'Foot.L', 'Body', 'Hips', 'Abdomen', 'Torso', 'Neck', 'Head', 'Shoulder.L', 'UpperArm.L', 'LowerArm.L', 'Pinky1.L', 'Pinky2.L', 'Pinky3.L', 'Middle1.L', 'Middle2.L', 'Middle3.L', 'Index1.L', 'Index2.L', 'Index3.L', 'Thumb1.L', 'Thumb2.L', 'Shoulder.R', 'UpperArm.R', 'LowerArm.R', 'Pinky1.R', 'Pinky2.R', 'Pinky3.R', 'Middle1.R', 'Middle2.R', 'Middle3.R', 'Index1.R', 'Index2.R', 'Index3.R', 'Thumb1.R', 'Thumb2.R', 'UpperLeg.L', 'LowerLeg.L', 'UpperLeg.R', 'LowerLeg.R', 'PoleTarget.L', 'Foot.R', 'PoleTarget.R']);

/**
 * Engine scale: bots.js scales a body by 1.83 / bodyHeight with these measured
 * heights, so model units per real metre = bodyHeight / 1.83.
 */
export const ENGINE_BODY_HEIGHT = Object.freeze({ ct: 2.2699, t: 2.1358 });
const UPM = { ct: ENGINE_BODY_HEIGHT.ct / 1.83, t: ENGINE_BODY_HEIGHT.t / 1.83 };

/** Real-world widths of the team-tinted kit regions per LOD (metres). */
export const KIT_TEAM_WIDTH = Object.freeze({ 0: { stripe: 0.06, patch: 1 }, 1: { stripe: 0.16, patch: 1.6 } });

// ---------------------------------------------------------------------------
// Geometry accumulator
// ---------------------------------------------------------------------------
const _v = new THREE.Vector3();
const _n = new THREE.Vector3();

/** Flip n if it points toward the centre c (c null: keep). */
function outward(n, p, c) {
  if (!c) return n.normalize();
  const toP = p.clone().sub(new THREE.Vector3(...c));
  return n.dot(toP) < 0 ? n.negate().normalize() : n.normalize();
}
/** Order a quad so its winding (counter-clockwise) faces along n. */
function orderOut(q, n) {
  const face = q[1].clone().sub(q[0]).cross(q[3].clone().sub(q[0]));
  return face.dot(n) >= 0 ? q : [q[0], q[3], q[2], q[1]];
}

class KitBuilder {
  constructor(boneIndex) {
    this.boneIndex = boneIndex;
    this.pos = []; this.nor = []; this.uv = []; this.si = []; this.sw = []; this.idx = [];
    this.parts = [];
    this._part = null;
  }

  part(name, bone) {
    this._part = { name, bone, tris: 0 };
    this.parts.push(this._part);
    return this;
  }

  _vert(p, n, slot) {
    const [u, v] = slotUV(slot);
    const b = this.boneIndex(this._part.bone);
    this.pos.push(p.x, p.y, p.z); this.nor.push(n.x, n.y, n.z); this.uv.push(u, v);
    this.si.push(b, 0, 0, 0); this.sw.push(1, 0, 0, 0);
    return this.pos.length / 3 - 1;
  }

  _tri(a, b, c) { this.idx.push(a, b, c); this._part.tris++; }

  /** Append an indexed three BufferGeometry under a transform, one slot. */
  geom(g, slot, matrix) {
    const gi = g;
    const P = gi.attributes.position, N = gi.attributes.normal;
    const nm = new THREE.Matrix3().getNormalMatrix(matrix);
    const base = this.pos.length / 3;
    for (let i = 0; i < P.count; i++) {
      _v.fromBufferAttribute(P, i).applyMatrix4(matrix);
      _n.fromBufferAttribute(N, i).applyMatrix3(nm).normalize();
      this._vert(_v, _n, slot);
    }
    const flip = matrix.determinant() < 0;
    if (gi.index) {
      const I = gi.index.array;
      for (let t = 0; t < I.length; t += 3) {
        if (flip) this._tri(base + I[t], base + I[t + 2], base + I[t + 1]);
        else this._tri(base + I[t], base + I[t + 1], base + I[t + 2]);
      }
    } else {
      for (let t = 0; t < P.count; t += 3) this._tri(base + t, base + t + (flip ? 2 : 1), base + t + (flip ? 1 : 2));
    }
    g.dispose();
    return this;
  }

  /** Quad a-b-c-d (counter-clockwise seen from the front), per-vertex or flat normals. */
  quad(a, b, c, d, slot, normals = null) {
    let ns = normals;
    if (!ns) {
      const n = new THREE.Vector3().subVectors(b, a).cross(new THREE.Vector3().subVectors(d, a)).normalize();
      ns = [n, n, n, n];
    }
    const i = [a, b, c, d].map((p, k) => this._vert(p, ns[k], slot));
    this._tri(i[0], i[1], i[2]); this._tri(i[0], i[2], i[3]);
    return this;
  }

  /** Square-section rod (box) between two points. */
  rod(from, to, thick, slot) {
    const a = new THREE.Vector3(...from), b = new THREE.Vector3(...to);
    const len = a.distanceTo(b);
    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), b.clone().sub(a).normalize());
    const m = new THREE.Matrix4().compose(a.clone().add(b).multiplyScalar(0.5), q, new THREE.Vector3(1, 1, 1));
    return this.geom(new THREE.BoxGeometry(thick, len, thick), slot, m);
  }

  box(size, slot, at, rot) {
    return this.geom(new THREE.BoxGeometry(size[0], size[1], size[2]), slot, M(at, rot));
  }

  cyl(rTop, rBot, h, seg, slot, at, rot, open = false) {
    return this.geom(new THREE.CylinderGeometry(rTop, rBot, h, seg, 1, open), slot, M(at, rot));
  }

  lathe(points, seg, slot, at, rot) {
    return this.geom(new THREE.LatheGeometry(points.map(([x, y]) => new THREE.Vector2(x, y)), seg), slot, M(at, rot));
  }

  /**
   * Ellipsoid patch. Azimuth `a` is measured around +Y from +Z (front), polar
   * `p` from the top (0) down. slotFn(aMid, pMid) picks the swatch per quad.
   */
  shell({ c, r, a0, a1, p0, p1, na, np, slotFn, inset = null }) {
    const pt = (a, p) => new THREE.Vector3(c[0] + r[0] * Math.sin(p) * Math.sin(a), c[1] + r[1] * Math.cos(p), c[2] + r[2] * Math.sin(p) * Math.cos(a));
    const nm = (q) => new THREE.Vector3((q.x - c[0]) / (r[0] * r[0]), (q.y - c[1]) / (r[1] * r[1]), (q.z - c[2]) / (r[2] * r[2])).normalize();
    for (let i = 0; i < na; i++) {
      const aA = a0 + (a1 - a0) * (i / na), aB = a0 + (a1 - a0) * ((i + 1) / na);
      for (let j = 0; j < np; j++) {
        const pA = p0 + (p1 - p0) * (j / np), pB = p0 + (p1 - p0) * ((j + 1) / np);
        const slot = slotFn((aA + aB) / 2, (pA + pB) / 2, i, j);
        if (!slot) continue;
        const q = [pt(aA, pA), pt(aA, pB), pt(aB, pB), pt(aB, pA)];
        if (pA === 0) { // pole: one triangle, not a degenerate quad
          const ns = q.map(nm);
          const iv = [q[0], q[1], q[2]].map((p, k) => this._vert(p, ns[k], slot));
          this._tri(iv[0], iv[1], iv[2]);
          continue;
        }
        this.quad(q[0], q[1], q[2], q[3], slot, q.map(nm));
      }
    }
    return this;
  }

  /**
   * Thick curved plate: an arc of a cylinder with radius rIn..rOut, around the
   * local Y axis, angles a0..a1 measured from local +Z toward +X, height h.
   * Placed by `matrix`. Smooth outer/inner faces, flat edges.
   */
  arc({ rIn, rOut, a0, a1, h, n, slot, matrix, edgeSlot = slot }) {
    const P = (r, a, y) => new THREE.Vector3(r * Math.sin(a), y, r * Math.cos(a)).applyMatrix4(matrix);
    const nm = new THREE.Matrix3().getNormalMatrix(matrix);
    const N = (a, s) => new THREE.Vector3(s * Math.sin(a), 0, s * Math.cos(a)).applyMatrix3(nm).normalize();
    const y0 = -h / 2, y1 = h / 2;
    for (let i = 0; i < n; i++) {
      const aA = a0 + (a1 - a0) * (i / n), aB = a0 + (a1 - a0) * ((i + 1) / n);
      this.quad(P(rOut, aA, y0), P(rOut, aB, y0), P(rOut, aB, y1), P(rOut, aA, y1), slot, [N(aA, 1), N(aB, 1), N(aB, 1), N(aA, 1)]);
      this.quad(P(rIn, aB, y0), P(rIn, aA, y0), P(rIn, aA, y1), P(rIn, aB, y1), slot, [N(aB, -1), N(aA, -1), N(aA, -1), N(aB, -1)]);
      this.quad(P(rIn, aA, y1), P(rOut, aA, y1), P(rOut, aB, y1), P(rIn, aB, y1), edgeSlot);
      this.quad(P(rIn, aB, y0), P(rOut, aB, y0), P(rOut, aA, y0), P(rIn, aA, y0), edgeSlot);
    }
    this.quad(P(rIn, a0, y0), P(rOut, a0, y0), P(rOut, a0, y1), P(rIn, a0, y1), edgeSlot);
    this.quad(P(rOut, a1, y0), P(rIn, a1, y0), P(rIn, a1, y1), P(rOut, a1, y1), edgeSlot);
    return this;
  }

  /** Prism from a 2D outline (CCW, XY plane), extruded `depth` along +Z, centred. */
  prism(outline, depth, slot, matrix) {
    const shape = new THREE.Shape(outline.map(([x, y]) => new THREE.Vector2(x, y)));
    const g = new THREE.ExtrudeGeometry(shape, { depth, bevelEnabled: false, curveSegments: 1, steps: 1 });
    g.translate(0, 0, -depth / 2);
    return this.geom(g, slot, matrix);
  }

  /**
   * Conformal shell over the measured head profile (see domeRadius): a grid
   * over azimuth a0..a1 / polar p0..p1. radiusFn(a, p) gives the radius;
   * slotFn(a, p, i, j) the swatch (null = hole).
   */
  conformal({ c, a0, a1, p0, p1, na, np, radiusFn, slotFn }) {
    const pt = (a, p) => {
      const r = radiusFn(a, p);
      return new THREE.Vector3(c[0] + r * Math.sin(p) * Math.sin(a), c[1] + r * Math.cos(p), c[2] + r * Math.sin(p) * Math.cos(a));
    };
    const nrm = (a, p) => {
      const e = 1e-3;
      const dp = pt(a, p + e).sub(pt(a, p - e));
      let da = pt(a + e, p).sub(pt(a - e, p));
      if (da.lengthSq() < 1e-12) return new THREE.Vector3(0, 1, 0);
      return da.cross(dp).normalize();
    };
    for (let i = 0; i < na; i++) {
      const aA = a0 + (a1 - a0) * (i / na), aB = a0 + (a1 - a0) * ((i + 1) / na);
      for (let j = 0; j < np; j++) {
        const pA = p0 + (p1 - p0) * (j / np), pB = p0 + (p1 - p0) * ((j + 1) / np);
        const slot = slotFn((aA + aB) / 2, (pA + pB) / 2, i, j);
        if (!slot) continue;
        const qa = [[aA, pA], [aA, pB], [aB, pB], [aB, pA]];
        const q = qa.map(([a, p]) => pt(a, p));
        const ns = qa.map(([a, p]) => (p < 1e-6 ? new THREE.Vector3(0, 1, 0) : outward(nrm(a, p), q[0], c)));
        if (pA < 1e-6) {
          const iv = [q[0], q[1], q[2]].map((p, k) => this._vert(p, ns[k], slot));
          this._tri(iv[0], iv[1], iv[2]);
        } else this.quad(q[0], q[1], q[2], q[3], slot, ns);
      }
    }
    return this;
  }

  /**
   * Band following the head profile along a meridian plane (azimuth `az` and
   * az + pi), from polar t0 on one side over the crown to t1 on the other.
   * Width w across the plane, standing `off` proud, `thick` high (side walls).
   */
  meridian({ c, az, w, off, thick = 0, t0, t1, n, slot, radiusFn }) {
    const across = new THREE.Vector3(Math.cos(az), 0, -Math.sin(az)); // perpendicular to the plane
    const surf = (t, side, extra) => {
      // t in [-T, T]: negative = the az+pi half. Point on the meridian, shifted across.
      const a = t >= 0 ? az : az + Math.PI, p = Math.abs(t);
      const dir = new THREE.Vector3(Math.sin(p) * Math.sin(a), Math.cos(p), Math.sin(p) * Math.cos(a));
      const base = new THREE.Vector3(...c).addScaledVector(dir, radiusFn(a, p)).addScaledVector(across, side * w / 2);
      const d2 = base.clone().sub(new THREE.Vector3(...c));
      const a2 = Math.atan2(d2.x, d2.z), p2 = Math.acos(Math.max(-1, Math.min(1, d2.y / d2.length())));
      const r2 = radiusFn(a2, p2) + off + extra;
      return new THREE.Vector3(...c).addScaledVector(d2.normalize(), r2);
    };
    const ts = Array.from({ length: n + 1 }, (_, k) => t0 + (t1 - t0) * (k / n));
    for (let k = 0; k < n; k++) {
      const A = ts[k], B = ts[k + 1];
      const tl = [surf(A, -1, thick), surf(A, 1, thick), surf(B, 1, thick), surf(B, -1, thick)];
      const nA = outward(tl[1].clone().sub(tl[0]).cross(tl[3].clone().sub(tl[0])), tl[0], c);
      this.quad(...orderOut(tl, nA), slot);
      if (thick > 0) {
        for (const side of [-1, 1]) {
          const q = [surf(A, side, 0), surf(B, side, 0), surf(B, side, thick), surf(A, side, thick)];
          const nn = across.clone().multiplyScalar(side);
          this.quad(...orderOut(q, nn), slot);
        }
      }
    }
    return this;
  }

  toGeometry() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.nor, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setAttribute('skinIndex', new THREE.Uint16BufferAttribute(this.si, 4));
    g.setAttribute('skinWeight', new THREE.Float32BufferAttribute(this.sw, 4));
    g.setIndex(this.idx);
    g.computeBoundingSphere();
    return g;
  }
}

const DEG = Math.PI / 180;
/** Matrix from position + Euler XYZ (degrees) + optional scale. */
function M(at = [0, 0, 0], rot = [0, 0, 0], scale = [1, 1, 1]) {
  return new THREE.Matrix4().compose(
    new THREE.Vector3(...at),
    new THREE.Quaternion().setFromEuler(new THREE.Euler(rot[0] * DEG, rot[1] * DEG, rot[2] * DEG)),
    new THREE.Vector3(...scale),
  );
}

// ---------------------------------------------------------------------------
// Anchors measured off the shipped bodies (body-metrics.js)
// ---------------------------------------------------------------------------
/**
 * Smooth, conservative radius of everything on the head, from the dome
 * profile's centre: bilinear over bin centres, never below the raw bin max.
 */
function domeRadiusFn(dome) {
  const { na, np, pmax, r } = dome;
  // 3x3 blur, clamped from below by the measured (dilated) maxima
  const sm = r.map((col, i) => col.map((v, j) => {
    let s = 0, k = 0;
    for (let di = -1; di <= 1; di++) for (let dj = -1; dj <= 1; dj++) {
      const jj = Math.min(np - 1, Math.max(0, j + dj));
      s += r[(i + di + na) % na][jj]; k++;
    }
    return Math.max(v, s / k);
  }));
  return (a, p) => {
    const fa = ((a + Math.PI) / (2 * Math.PI)) * na - 0.5;
    const fp = Math.min(np - 1, Math.max(0, (p / pmax) * np - 0.5));
    const i0 = Math.floor(fa), ta = fa - i0;
    const j0 = Math.min(np - 2, Math.floor(fp)), tp = fp - j0;
    const g = (i, j) => sm[((i % na) + na) % na][j];
    const top = g(i0, j0) * (1 - ta) + g(i0 + 1, j0) * ta;
    const bot = g(i0, j0 + 1) * (1 - ta) + g(i0 + 1, j0 + 1) * ta;
    return top * (1 - tp) + bot * tp;
  };
}

function anchors(body) {
  const m = BODY_METRICS[body];
  const t = m.torso;
  const R = domeRadiusFn(m.dome);
  return {
    m, upm: UPM[body],
    c: m.dome.c, R,
    halfW: m.helmet.max[0], rim: m.dome.c[1],
    chestZ: t.max[2], backZ: t.min[2], torsoX: t.max[0],
    beltY: (m.belt.min[1] + m.belt.max[1]) / 2, beltZ: m.belt.max[2], beltX: m.belt.max[0], beltBack: m.belt.min[2],
    knee: [(m.lowerLegL.min[0] + m.lowerLegL.max[0]) / 2, m.lowerLegL.max[1] - 0.06, m.lowerLegL.max[2]],
  };
}

// ---------------------------------------------------------------------------
// Reusable gear pieces
// ---------------------------------------------------------------------------
/** Shooter's-cut plate outline (top corners chamfered), centred. */
function plateOutline(w, h, cut) {
  return [[-w / 2, -h / 2], [w / 2, -h / 2], [w / 2, h / 2 - cut], [w / 2 - cut, h / 2], [-w / 2 + cut, h / 2], [-w / 2, h / 2 - cut]];
}

/** Plate carrier: shooter's-cut front + back plates, cummerbund, shoulder straps, pouches. */
function plateCarrier(k, A, { heavy = false, lod = 0, pouches = 0 } = {}) {
  const w = heavy ? 0.54 : 0.46, hgt = heavy ? 0.46 : 0.38, d = heavy ? 0.085 : 0.06;
  const y = heavy ? 1.245 : 1.27;
  const zf = A.chestZ + d / 2 - 0.012, zb = A.backZ - d / 2 + 0.012;
  k.part(heavy ? 'heavy plate carrier' : 'light plate carrier', 'Torso');
  k.prism(plateOutline(w, hgt, heavy ? 0.12 : 0.1), d, 'PLATE', M([0, y, zf], [-4, 0, 0]));
  k.prism(plateOutline(w, hgt + 0.04, 0.08), d, 'PLATE', M([0, y + 0.01, zb], [4, 0, 0]));
  // cummerbund: side panels joining the plates
  for (const s of [-1, 1]) k.box([0.05, heavy ? 0.24 : 0.18, (zf - zb) * 0.92], 'PLATE', [s * (A.torsoX + 0.004), y - 0.09, (zf + zb) / 2]);
  if (lod === 0) {
    for (const s of [-1, 1]) k.box([0.085, 0.04, zf - zb - 0.03], 'STRAP', [s * 0.165, 1.49, (zf + zb) / 2], [0, 0, s * -8]);
    for (let i = 0; i < pouches; i++) {
      const x = (i - (pouches - 1) / 2) * (w / (pouches + 0.35));
      k.box([w / (pouches + 1.1), 0.13, 0.06], 'POUCH', [x, y - hgt / 2 + 0.075, zf + d / 2 + 0.022]);
    }
  } else if (pouches) {
    k.box([w * 0.8, 0.12, 0.05], 'POUCH', [0, y - hgt / 2 + 0.07, zf + d / 2 + 0.02]);
  }
  return { zf: zf + d / 2, zb: zb - d / 2, y };
}

/** Team-tinted velcro patch (flat box). LOD1 patches are bigger. */
function patch(k, bone, at, rot, size, lod) {
  const s = KIT_TEAM_WIDTH[lod].patch;
  k.part('team patch', bone);
  k.box([size[0] * s, size[1] * s, size[2]], 'PATCH', at, rot);
}

/** Team stripe over the crown of a kit shell (hood / cap), conforming. */
function crownStripe(k, A, off, lod, t0, t1, radiusFn = A.R) {
  const w = KIT_TEAM_WIDTH[lod].stripe * A.upm;
  k.meridian({ c: A.c, az: 0, w, off, t0, t1, n: lod === 0 ? 10 : 6, slot: 'STRIPE', radiusFn });
}

/** Slim comms headset: ear cups + boom mic (Head bone). */
function headset(k, A, lod) {
  const seg = lod === 0 ? 8 : 6;
  k.part('headset', 'Head');
  for (const s of [-1, 1]) {
    const r = A.R(s * Math.PI / 2, Math.PI * 0.52);
    k.cyl(0.085, 0.085, 0.06, seg, 'GEAR_GREY', [s * (r + 0.02), A.c[1] - 0.02, A.c[2]], [0, 0, 90]);
  }
  if (lod === 0) {
    // boom mic: from the right cup, hugging the cheek, to the mouth
    const r = A.R(-Math.PI / 2, Math.PI * 0.52);
    const cup = [-(r + 0.03), A.c[1] - 0.06, A.c[2] + 0.05];
    const cheek = [-(r - 0.02), A.c[1] - 0.17, A.c[2] + 0.22];
    const mouth = [-0.13, A.c[1] - 0.2, A.m.dome.c[2] + A.R(0, Math.PI * 0.62) - 0.02];
    k.rod(cup, cheek, 0.026, 'RUBBER');
    k.rod(cheek, mouth, 0.026, 'RUBBER');
    k.box([0.055, 0.045, 0.05], 'RUBBER', mouth);
  }
}

// ---------------------------------------------------------------------------
// Operators (DESIGN.md §4.2 / §9.2)
// ---------------------------------------------------------------------------
export const OPERATORS = Object.freeze({
  cinder: { name: 'Cinder', side: 'attack', body: { attack: 'ct', defend: 'ct' }, bodyType: 'Heavy', read30m: 'Wide, hunched, tank bump' },
  wren: { name: 'Wren', side: 'attack', body: { attack: 't', defend: 't' }, bodyType: 'Light', read30m: 'Thin, with a vertical antenna line' },
  hush: { name: 'Hush', side: 'defend', body: { attack: 'ct', defend: 'ct' }, bodyType: 'Standard', read30m: 'Square back, round ear cups' },
  latch: { name: 'Latch', side: 'defend', body: { attack: 't', defend: 't' }, bodyType: 'Light', read30m: 'Cap brim, waist bulk' },
  cadet: { name: 'Cadet', side: 'both', body: { attack: 't', defend: 'ct' }, bodyType: 'Standard', read30m: 'Neutral' },
});

/** Which body GLB an operator uses on a side ('ct' | 't'). */
export function bodyFor(operator, side) {
  const op = OPERATORS[operator];
  if (!op) throw new Error(`unknown operator ${operator}`);
  return op.body[side] || op.body.attack;
}

const BUILDERS = {
  // Heavy breacher: heavy plate carrier, welder's visor flipped up, broad
  // pauldrons and a cutting-gas tank on the back.
  cinder(k, A, lod) {
    const pc = plateCarrier(k, A, { heavy: true, lod, pouches: 3 });
    // Welder visor, flipped up over the brow: a thick curved shield hinged at
    // the helmet sides and rotated up ~68 degrees.
    k.part('welder visor (up)', 'Head');
    const rs = A.R(Math.PI / 2, Math.PI / 2);
    const hinge = [0, A.c[1] + 0.03, A.c[2] + 0.02];
    const up = M(hinge, [-66, 0, 0]).multiply(M([0, -0.15, 0]));
    const rv = Math.max(rs, A.R(0, Math.PI / 2) - 0.02) + 0.05;
    k.arc({ rIn: rv, rOut: rv + 0.03, a0: -64 * DEG, a1: 64 * DEG, h: 0.3, n: lod === 0 ? 8 : 4, slot: 'GEAR_GREY', edgeSlot: 'METAL_DARK', matrix: up });
    if (lod === 0) {
      k.arc({ rIn: rv + 0.025, rOut: rv + 0.045, a0: -34 * DEG, a1: 34 * DEG, h: 0.1, n: 4, slot: 'LENS', matrix: up.clone().multiply(M([0, 0.02, 0])) });
      for (const s of [-1, 1]) k.cyl(0.065, 0.065, 0.05, 6, 'METAL_DARK', [s * (rs + 0.04), hinge[1], hinge[2]], [0, 0, 90]);
    }
    // Broad pauldrons layered over the base shoulder pads, ending above the armband.
    for (const s of [-1, 1]) {
      const side = s > 0 ? 'L' : 'R';
      k.part(`pauldron ${side}`, `UpperArm.${side}`);
      k.arc({ rIn: 0.135, rOut: 0.175, a0: -78 * DEG, a1: 78 * DEG, h: 0.2, n: lod === 0 ? 6 : 3, slot: 'PLATE', edgeSlot: 'STRAP', matrix: M([s * 0.31, 1.44, -0.03], [0, 0, s * -90]).multiply(M([0, 0, 0], [-90, 0, 0])) });
    }
    // Gas tank on the back plate, with valve, hose and a stencil band.
    k.part('back tank', 'Torso');
    const tr = 0.14, hh = 0.27, tz = pc.zb - tr + 0.01;
    k.lathe([[0, -hh - 0.05], [tr * 0.7, -hh - 0.03], [tr, -hh + 0.04], [tr, hh - 0.04], [tr * 0.7, hh + 0.03], [0, hh + 0.05]], lod === 0 ? 8 : 6, 'METAL', [0, 1.2, tz]);
    if (lod === 0) {
      k.cyl(0.035, 0.035, 0.08, 6, 'METAL_DARK', [0, 1.2 + hh + 0.08, tz]);
      k.box([0.3, 0.05, 0.03], 'STRAP', [0, 1.34, tz + tr - 0.012]);
      k.box([0.3, 0.05, 0.03], 'STRAP', [0, 1.06, tz + tr - 0.012]);
      k.box([0.03, 0.03, 0.34], 'RUBBER', [-0.13, 1.12, tz + 0.05], [30, 0, 0]);
      k.cyl(tr + 0.004, tr + 0.004, 0.07, 8, 'KIT_LIGHT', [0, 1.2, tz], [0, 0, 0], true);
    }
  },

  // Light recon: soft hood over the helmet, long whip antenna rising past the
  // LEFT shoulder from a small radio, light plate carrier.
  wren(k, A, lod) {
    plateCarrier(k, A, { lod, pouches: 2 });
    k.part('hood', 'Head');
    const off = 0.045;
    const rimR = (a) => A.R(a, Math.PI / 2) + off;
    // Hood radius: conform above the rim; below it, drape outward over the
    // neck and shoulders instead of following the narrow neck.
    // soft peak at the back of the crown, where the fabric gathers
    const peak = (a, p) => 0.06 * Math.max(0, Math.cos(a - Math.PI)) ** 3 * Math.exp(-(((p - Math.PI * 0.3) / 0.32) ** 2));
    const hoodR = (a, p) => (p <= Math.PI / 2 ? A.R(a, p) + off + peak(a, p) : rimR(a) * (1 + 0.22 * (p - Math.PI / 2)));
    const face = 52 * DEG, faceTop = Math.PI * 0.32, pEnd = Math.PI * 0.66;
    const np = lod === 0 ? 8 : 6;
    k.conformal({
      c: A.c, a0: -Math.PI, a1: Math.PI, p0: 0, p1: pEnd, na: lod === 0 ? 16 : 10, np, radiusFn: hoodR,
      slotFn: (a, p) => {
        if (Math.abs(a) < face && p > faceTop) return null;            // face opening
        if (p > Math.PI / 2 && Math.abs(a) < 95 * DEG) return null;    // drape only at the back
        // LOD1: tinted band around the hood, like the helmets' LOD1 band
        if (lod === 1 && p > Math.PI * 0.36 && p < Math.PI * 0.5) return 'STRIPE';
        return 'HOOD';
      },
    });
    crownStripe(k, A, 0.006, lod, -Math.PI * 0.5, faceTop - 0.02, hoodR);
    // Radio on the left shoulder blade + 0.5 m whip antenna, leaning out so it
    // clears the head silhouette from the front.
    k.part('radio + whip antenna', 'Torso');
    const ax = 0.27, az = A.backZ - 0.05, lean = 14;
    k.box([0.12, 0.2, 0.08], 'KIT_DARK', [ax - 0.04, 1.33, az]);
    const len = 0.5 * A.upm;
    const thick = lod === 0 ? 0.024 : 0.04;
    const base = new THREE.Vector3(ax, 1.43, az);
    const dir = new THREE.Vector3(Math.sin(lean * DEG), Math.cos(lean * DEG), 0);
    const mid = base.clone().addScaledVector(dir, len / 2), tip = base.clone().addScaledVector(dir, len);
    k.box([thick, len, thick], 'RUBBER', mid.toArray(), [0, 0, -lean]);
    k.box([0.05, 0.05, 0.05].map((x) => x * (lod === 0 ? 1 : 1.5)), 'TEAM_LIGHT', tip.toArray(), [0, 0, -lean]);
    if (lod === 0) k.cyl(0.03, 0.03, 0.07, 6, 'METAL_DARK', base.clone().addScaledVector(dir, 0.02).toArray(), [0, 0, -lean]);
  },

  // Signals defender: boxy backpack with a small dish, ear-defender cups on a
  // headband over the helmet.
  hush(k, A, lod) {
    k.part('backpack + dish', 'Torso');
    const bz = A.backZ - 0.13;
    k.box([0.48, 0.52, 0.24], 'KIT_DARK', [0, 1.22, bz]);
    if (lod === 0) {
      k.box([0.5, 0.07, 0.26], 'POUCH', [0, 1.475, bz]);
      for (const s of [-1, 1]) k.box([0.06, 0.24, 0.17], 'POUCH', [s * 0.27, 1.12, bz]);
      k.box([0.3, 0.16, 0.03], 'GEAR_GREY', [0, 1.08, bz - 0.13]);
    }
    // dish on a mast from the right top corner, facing up and back
    const mast = [-0.17, 1.5, bz - 0.04];
    k.cyl(0.022, 0.022, 0.3, 6, 'METAL_DARK', [mast[0], mast[1] + 0.15, mast[2]], [-12, 0, 0]);
    const dishAt = [mast[0], mast[1] + 0.31, mast[2] - 0.07];
    k.lathe([[0.0, -0.005], [0.08, 0.012], [0.15, 0.05], [0.165, 0.065], [0.15, 0.058], [0.0, 0.01]], lod === 0 ? 10 : 6, 'METAL', dishAt, [-50, 0, 0]);
    if (lod === 0) k.box([0.035, 0.035, 0.035], 'TEAM_LIGHT', [dishAt[0], dishAt[1] + 0.05, dishAt[2] - 0.05]);
    // Ear defenders: big round cups on a headband over the crown.
    k.part('ear defenders', 'Head');
    const seg = lod === 0 ? 10 : 6;
    for (const s of [-1, 1]) {
      const r = A.R(s * Math.PI / 2, Math.PI * 0.5);
      k.cyl(0.135, 0.135, 0.1, seg, 'GEAR_GREY', [s * (r + 0.05), A.c[1] - 0.01, A.c[2] - 0.02], [0, 0, 90]);
      if (lod === 0) k.cyl(0.12, 0.12, 0.03, seg, 'RUBBER', [s * (r + 0.005), A.c[1] - 0.01, A.c[2] - 0.02], [0, 0, 90]);
    }
    k.meridian({ c: A.c, az: Math.PI / 2, w: 0.08, off: 0.02, thick: 0.03, t0: -Math.PI * 0.47, t1: Math.PI * 0.47, n: lod === 0 ? 10 : 5, slot: 'GEAR_GREY', radiusFn: A.R });
  },

  // Trapper defender: peaked cap over the helmet, three snare-wire spools on
  // the belt, knee pads, light plate carrier.
  latch(k, A, lod) {
    plateCarrier(k, A, { lod, pouches: 2 });
    k.part('peaked cap', 'Head');
    const off = 0.03;
    const pEnd = Math.PI * 0.5;
    const np = lod === 0 ? 5 : 3;
    k.conformal({
      c: A.c, a0: -Math.PI, a1: Math.PI, p0: 0, p1: pEnd, na: lod === 0 ? 16 : 10, np, radiusFn: (a, p) => A.R(a, p) + off,
      slotFn: (a, p, i, j) => (j === np - 1 ? 'STRIPE' : 'CAP'), // tinted band around the cap
    });
    if (lod === 0) k.box([0.07, 0.03, 0.07], 'CAP', [0, A.c[1] + A.R(0, 0) + off + 0.01, A.c[2]]); // button
    // Brim: a flat plate following the cap front, projecting forward.
    k.part('cap brim', 'Head');
    const n = lod === 0 ? 7 : 4, a0 = -62 * DEG, a1 = 62 * DEG, yb = A.rim + 0.005, th = 0.028;
    const ring = (a, out, y) => {
      const r = A.R(a, Math.PI / 2) + off - 0.01 + out * (0.55 + 0.45 * Math.cos(a * 1.25));
      return new THREE.Vector3(A.c[0] + r * Math.sin(a), y - out * 0.18, A.c[2] + r * Math.cos(a));
    };
    for (let i = 0; i < n; i++) {
      const aA = a0 + (a1 - a0) * (i / n), aB = a0 + (a1 - a0) * ((i + 1) / n);
      const L = 0.19;
      k.quad(ring(aA, 0, yb + th), ring(aA, L, yb + th), ring(aB, L, yb + th), ring(aB, 0, yb + th), 'CAP', null);
      k.quad(ring(aB, 0, yb), ring(aB, L, yb), ring(aA, L, yb), ring(aA, 0, yb), 'KIT_DARK', null);
      k.quad(ring(aA, L, yb), ring(aB, L, yb), ring(aB, L, yb + th), ring(aA, L, yb + th), 'CAP', null);
    }
    // spools: reels of snare wire on the belt
    k.part(lod === 0 ? 'snare spools x3' : 'snare spools x2', 'Hips');
    const spots = lod === 0 ? [[-1, 35], [-1, 88], [1, 75]] : [[-1, 60], [1, 75]];
    for (const [s, deg] of spots) {
      const a = deg * DEG;
      const x = s * Math.sin(a) * (A.beltX + 0.05), z = Math.cos(a) * (A.beltZ + 0.05) - 0.02;
      const mat = M([x, A.beltY - 0.03, z], [0, s * deg, 0]);
      const seg = lod === 0 ? 7 : 5, rot = [90, 0, 0];
      k.geom(new THREE.CylinderGeometry(0.095, 0.095, 0.022, seg), 'KIT_DARK', mat.clone().multiply(M([0, 0, 0.045], rot)));
      k.geom(new THREE.CylinderGeometry(0.095, 0.095, 0.022, seg), 'KIT_DARK', mat.clone().multiply(M([0, 0, -0.035], rot)));
      k.geom(new THREE.CylinderGeometry(0.075, 0.075, 0.07, seg, 1, true), 'KIT_LIGHT', mat.clone().multiply(M([0, 0, 0.005], rot)));
    }
    // knee pads
    for (const s of [-1, 1]) {
      const side = s > 0 ? 'L' : 'R';
      k.part(`knee pad ${side}`, `LowerLeg.${side}`);
      k.box([0.17, 0.17, 0.06], 'PAD', [s * A.knee[0], A.knee[1], A.knee[2] + 0.005], [-6, 0, 0]);
      if (lod === 0) k.box([0.18, 0.04, 0.19], 'STRAP', [s * A.knee[0], A.knee[1] - 0.03, A.knee[2] - 0.085]);
    }
  },

  // Generic recruit: the body's plain helmet, a slim headset, team patches on
  // chest and back and — on the slimmer t body — a light plate carrier.
  cadet(k, A, lod, body) {
    let zf = A.chestZ + 0.012, zb = A.backZ - 0.012;
    if (body === 't') { const pc = plateCarrier(k, A, { lod, pouches: 3 }); zf = pc.zf + 0.006; zb = pc.zb - 0.006; }
    headset(k, A, lod);
    patch(k, 'Torso', [0.11, 1.4, zf], [-4, 0, 0], [0.13, 0.085, 0.02], lod);
    patch(k, 'Torso', [0, 1.37, zb], [4, 0, 0], [0.2, 0.12, 0.02], lod);
  },
};

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------
const stripDots = (s) => String(s).replace(/[.\s:/[\]]/g, '');

/** Bone-name -> skin index resolver for a three Skeleton, or the canonical order. */
export function boneIndexResolver(skeleton) {
  const names = skeleton ? skeleton.bones.map((b) => stripDots(b.name)) : JOINTS.map(stripDots);
  return (name) => {
    const i = names.indexOf(stripDots(name));
    if (i < 0) throw new Error(`bone ${name} not in skeleton`);
    return i;
  };
}

/**
 * Build one operator's kit as a skinned BufferGeometry in body bind space.
 * @param {string} operator  cinder | wren | hush | latch | cadet
 * @param {{ body?: 'ct'|'t', side?: 'attack'|'defend', lod?: 0|1, skeleton?: THREE.Skeleton }} opts
 * @returns {{ geometry: THREE.BufferGeometry, tris: number, parts: {name, bone, tris}[], bones: string[], body: string }}
 */
export function buildKit(operator, { body, side = 'attack', lod = 0, skeleton = null } = {}) {
  const op = OPERATORS[operator];
  if (!op) throw new Error(`unknown operator ${operator}`);
  const b = body || bodyFor(operator, side);
  const k = new KitBuilder(boneIndexResolver(skeleton));
  BUILDERS[operator](k, anchors(b), lod, b);
  const geometry = k.toGeometry();
  geometry.name = `kit_${operator}_${b}_lod${lod}`;
  return {
    geometry, body: b, tris: k.idx.length / 3,
    parts: k.parts.filter((p) => p.tris > 0),
    bones: [...new Set(k.parts.filter((p) => p.tris > 0).map((p) => p.bone))],
  };
}

/** Float32, non-interleaved copy of any (normalized / interleaved) attribute. */
function toFloat(attr, Ctor = Float32Array) {
  const out = new Ctor(attr.count * attr.itemSize);
  for (let i = 0; i < attr.count; i++) for (let c = 0; c < attr.itemSize; c++) out[i * attr.itemSize + c] = attr.getComponent(i, c);
  return new THREE.BufferAttribute(out, attr.itemSize);
}

/**
 * Merge a kit into a body geometry (one draw call). Handles the quantised,
 * normalised attribute types GLTFLoader produces for the meshopt bodies.
 * Returns a NEW geometry; dispose the old one yourself if nothing else uses it.
 */
export function mergeKitIntoBody(bodyGeometry, kitGeometry) {
  const parts = [bodyGeometry, kitGeometry];
  const names = ['position', 'normal', 'uv', 'skinIndex', 'skinWeight'];
  let vertCount = 0, idxCount = 0;
  for (const g of parts) { vertCount += g.attributes.position.count; idxCount += g.index ? g.index.count : g.attributes.position.count; }
  const out = new THREE.BufferGeometry();
  const arrays = {
    position: new Float32Array(vertCount * 3), normal: new Float32Array(vertCount * 3), uv: new Float32Array(vertCount * 2),
    skinIndex: new Uint16Array(vertCount * 4), skinWeight: new Float32Array(vertCount * 4),
  };
  const index = vertCount > 65535 ? new Uint32Array(idxCount) : new Uint16Array(idxCount);
  let vo = 0, io = 0;
  for (const g of parts) {
    for (const n of names) {
      const a = g.attributes[n];
      const f = toFloat(a, n === 'skinIndex' ? Uint16Array : Float32Array);
      arrays[n].set(f.array, vo * a.itemSize);
    }
    const count = g.attributes.position.count;
    if (g.index) for (let i = 0; i < g.index.count; i++) index[io++] = g.index.getX(i) + vo;
    else for (let i = 0; i < count; i++) index[io++] = i + vo;
    vo += count;
  }
  out.setAttribute('position', new THREE.BufferAttribute(arrays.position, 3));
  out.setAttribute('normal', new THREE.BufferAttribute(arrays.normal, 3));
  out.setAttribute('uv', new THREE.BufferAttribute(arrays.uv, 2));
  out.setAttribute('skinIndex', new THREE.BufferAttribute(arrays.skinIndex, 4));
  out.setAttribute('skinWeight', new THREE.BufferAttribute(arrays.skinWeight, 4));
  out.setIndex(new THREE.BufferAttribute(index, 1));
  out.computeBoundingBox();
  out.computeBoundingSphere();
  return out;
}

// ---------------------------------------------------------------------------
// Runtime textures / material
// ---------------------------------------------------------------------------

function dataTexture(px, srgb) {
  const t = new THREE.DataTexture(px, PALETTE_SIZE, PALETTE_SIZE, THREE.RGBAFormat);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter; t.generateMipmaps = false;
  t.flipY = false; t.needsUpdate = true;
  return t;
}

let _mask = null;
/** Shared emissive mask (white on the four team swatches). */
export function teamMaskTexture() { return _mask || (_mask = dataTexture(emissiveMaskRGBA(), true)); }

/** Palette DataTexture for one side and viewer-relative tint ('ally'|'enemy'|hex|null). */
export function paletteTexture(side = 'attack', tint = null, overrides = null) { return dataTexture(paletteRGBA(side, tint, overrides), true); }

/**
 * The one operator material. Potato/low tiers: Lambert; medium+: Standard.
 * Variants needed in a match: 2 sides x 2 tints = 4 materials total, shared by
 * every operator (attachments are already merged into the body geometry).
 */
export function operatorMaterial({ side = 'attack', tint = 'enemy', lambert = false } = {}) {
  const hex = TINTS[tint] || tint;
  const params = {
    map: paletteTexture(side, tint), emissiveMap: teamMaskTexture(),
    emissive: new THREE.Color(hex), emissiveIntensity: TEAM_EMISSIVE_INTENSITY,
  };
  const m = lambert ? new THREE.MeshLambertMaterial(params) : new THREE.MeshStandardMaterial({ ...params, roughness: 0.85, metalness: 0 });
  m.name = `operator_${side}_${tint}`;
  return m;
}

// ---------------------------------------------------------------------------
// Pipeline hooks (used by tools/build.mjs)
// ---------------------------------------------------------------------------
/** Triangle counts and bones per operator / body / LOD. */
export function attachmentReport() {
  const out = {};
  for (const op of Object.keys(OPERATORS)) {
    for (const body of [...new Set(Object.values(OPERATORS[op].body))]) {
      const k0 = buildKit(op, { body, lod: 0 }), k1 = buildKit(op, { body, lod: 1 });
      out[`${op}/${body}`] = { lod0: k0.tris, lod1: k1.tris, bones: k0.bones, parts: k0.parts.map((p) => `${p.name} (${p.bone}, ${p.tris})`) };
      k0.geometry.dispose(); k1.geometry.dispose();
    }
  }
  return out;
}


export { SLOTS as PALETTE_SLOTS };
